import json,re,random,chess,time
P=json.load(open("/tmp/obench-cell-79jyxh4f/bench_opencode_regex-chess_hw9fw5w3/re.json"))
def run(fen):
    for a,b in P: fen=re.sub(a,b,fen)
    return fen.split("\n")
def ref(fen):
    b=chess.Board(fen); s=set()
    for m in b.legal_moves:
        if m.promotion and m.promotion!=chess.QUEEN: continue
        c=b.copy(); c.push(m); s.add(" ".join(c.fen().split()[:-2]))
    return s
def ok(fen):
    ours=[" ".join(x.split(" ")[:-2]) for x in run(fen)]
    r=ref(fen)
    if len(ours)!=len(r): return False
    return all(x in r or x.rpartition(" ")[0]+" -" in r for x in ours)
ex="<REDACTED_B64> w kq - 0 1"
print(run(ex)); print(ok(ex))
random.seed(1); n=0; bad=0; t=time.time()
for g in range(300):
    b=chess.Board()
    for ply in range(random.randint(1,200)):
        if b.is_game_over(): break
        if b.turn==chess.WHITE and any(True for _ in b.legal_moves):
            n+=1
            if not ok(b.fen()):
                bad+=1
                if bad<5: print("BAD",b.fen())
        ms=list(b.legal_moves)
        # bias toward captures/promos/castles
        b.push(random.choice(ms))
print(n,bad,time.time()-t)
